/**
 * Integration tests — taskdag × llm-dag-generator cross-package wiring.
 *
 * Tests that DAGs generated by llm-dag-generator (fallback heuristic mode)
 * can be validated, executed, and replanned by the taskdag engine, covering
 * the full generate → validate → execute → fail → replan workflow.
 */

import { beforeEach, describe, expect, test } from "bun:test"

// llm-dag-generator
import { DAGGenerator, LLMDAGGenerator, createLLMDAGGenerator } from "../../llm-dag-generator/src/index"
import type { Capability } from "../../llm-dag-generator/src/index"

// taskdag
import {
  allSucceeded,
  estimateDAGCost,
  getReadyNodes,
  getTransitiveDependents,
  isComplete,
  markNodeFailed,
  replaceSubtree,
  validateDAG,
} from "../src/index"
import type { DAG, DAGNode } from "../src/index"

// ── Helpers ────────────────────────────────────────────────────────────────

